<template>
  <v-container>
    <v-toolbar color="primary" dark>
      <v-toolbar-title>part 1</v-toolbar-title>
    </v-toolbar>



    <v-data-table v-model="gridData" :headers="headers" :items="gridData" item-value="id" class="elevation-1"
      @paste="handlePaste">

      <template v-slot:no-data>
        <v-btn @click="updateRow">Update Header - sec A</v-btn>
        <h1>{{projectId}}</h1>
      </template>
    </v-data-table>



    <v-progress-linear v-if="loading" indeterminate color="primary"></v-progress-linear>



    <!-- Dialog for PasteProjectDetail -->
    <v-dialog v-model="dialog" max-width="800px">
      <v-card>
        <v-card-title>
          <span class="headline">Paste Project Header - 2</span>
        </v-card-title>
        <v-card-text>
   <h1>{{projectId}}</h1>

          <v-text-field v-model="newProject.branch" label="Branch" required></v-text-field>

          <v-text-field v-model="newProject.project" label="Project" required></v-text-field>
          <v-text-field v-model="newProject.projectType" label="Project Type" required></v-text-field>

          <v-text-field v-model="newProject.eumPicName" label="EUM PIC Name" required></v-text-field>

          <v-text-field v-model="newProject.eumPicContactNo" label="EUM PIC Contact No" 
            required></v-text-field>





          <v-text-field v-model="newProject.contractStartDate" label="Contract Start Date" type="date"
            required></v-text-field>


          <v-text-field v-model="newProject.contractExpiryDate" label="Contract End Date" type="date"
            required></v-text-field>

          <v-text-field v-model="newProject.rebate" label="Rebate"  required></v-text-field>

        
          <v-checkbox v-model="newProject.status" label="Active"></v-checkbox>

          <v-text-field v-model="newProject.title" label="Title" required></v-text-field>

          <v-text-field v-model="newProject.priceRange" label="Price Range" required></v-text-field>

          <v-text-field v-model="newProject.sizeRange" label="Size Range" required></v-text-field>

              </v-card-text>
        <v-card-actions>
          <v-btn color="primary" @click="submitProject">Submit</v-btn>
          <v-btn @click="closeDialog">Close</v-btn>
        </v-card-actions>
      </v-card>
      <v-btn @click="updateRow">Update Header Data</v-btn>

    </v-dialog>
    
     
  </v-container>
</template>

<script>
import { ref } from 'vue';
import { updateProjectRec } from '../utils/contactUtils'; // Import the mutation function

export default {
  name: 'ProjectListing',
  components: {

  },
  props: {
    projectId: {
      type: String,
      default: '', 
      required: true,
    },
  },
  setup(props) {
    const gridData = ref([]); // Holds grid data
    const headers = [
      { text: 'title', title: "title", value: 'title' },
      { text: 'description', title: "description", value: 'description' },

    ];

    const updateRow = async () => {
  try {
    const newLayout = {
      title: newProject.value.title,
      status: newProject.value.status,
      priceRange: newProject.value.priceRange,
      sizeRange: newProject.value.sizeRange,
   
      contractStartDate: newProject.value.contractStartDate,
      contractExpiryDate: newProject.value.contractExpiryDate,
      rebate: newProject.value.rebate,
    };
    
    await updateProjectRec(props.projectId, newLayout);
    
    alert('Data successfully exported to Strapi!');
  } catch (error) {
    console.error('Error exporting data to Strapi:', error);
    alert('Failed to export data.');
  }
};


    const loading = ref(false);
    const error = ref(null);
    const dialog = ref(false);
    const selectedProjectId = ref(null);

    const newProject = ref({
      branch: '',
      project: '',
      projectType: '',
      eumPicName: '',
      eumPicContactNo: '',
      agentComm:'',
      advanceComm:'',
      contractStartDate: '',
      contractExpiry: '',
      rebate: '',
      status: '',
      active: false,
      title: '',
      priceRange: '',
      sizeRange: '',
  
    });

      const handlePaste = (event) => {
      console.log("****1");
      const clipboardData = event.clipboardData || window.clipboardData;
      let pastedText = clipboardData.getData('text/plain');

      // Assuming tab-separated values for simplicity
      pastedText = pastedText.replaceAll("\t\r\n", "~");
      pastedText = pastedText.replaceAll("\r\n", "|");
      pastedText = pastedText.replaceAll("Contract Expiry Date~Rebate", `Contract Expiry Date~-|Rebate`);
      const rows = pastedText.trim().split('|').filter((row) => row.trim() !== '');

      const parsedData = rows.map((row) => {
        const columns = row.split('~');
        return {
          title: columns[0] || '',
          description: columns[1] || '',
        };
      });
      console.log("****2");
      parsedData.forEach((item) => {

     

if (item.title === 'Branch') newProject.value.branch = item.description;
if (item.title === 'Project Name') newProject.value.project = item.description;
if (item.title === 'Project Type') newProject.value.projectType = item.description;
if (item.title === 'EUM PIC Name') newProject.value.eumPicName = item.description;
if (item.title === 'EUM PIC Contact No') newProject.value.eumPicContactNo = item.description;
if (item.title === 'Agent Comm.') newProject.value.agentComm = item.agentComm;
if (item.title === 'Advance Comm.') newProject.value.advanceComm = item.advanceComm;


        if (item.title === 'Contract Start Date') newProject.value.title = item.description;
        if (item.title === 'Contract Expiry Date') newProject.value.priceRange = item.description;
        if (item.title === 'Rebate') newProject.value.rebate = item.description;
        if (item.title === 'Status') newProject.value.status = item.description=="Active"?true:false;

      });
      gridData.value = [...gridData.value, ...parsedData];
      dialog.value = true;
    };



    const openDialog = (id) => {
      selectedProjectId.value = id;
      dialog.value = true;
    };

   

    const closeDialog = () => {
  console.log('Close button clicked');
  dialog.value = false;
  selectedProjectId.value = null;
  resetNewProject();
};

    const resetNewProject = () => {
      newProject.value = {
        contractStartDate: '',
        contractExpiryDate: '',
        rebate: '',
        status: '',
        active: false,
        title: '',
        priceRange: '',
        sizeRange: '',

      };
    };

    const submitProject = () => {
      console.log('New Project Data:', newProject.value);
      closeDialog();
    };

    return {
      headers,
      loading,
      error,
      openDialog,
      closeDialog,
      dialog,
      selectedProjectId,
      newProject,
      submitProject,
      handlePaste,
      gridData,
      updateRow
    };
  },
};
</script>

<style scoped>
.elevation-1 {
  min-height: 300px;
}
</style>
