<template>
    <v-container>
      <v-toolbar color="primary" dark>
        <v-toolbar-title>Project Listings</v-toolbar-title>
      </v-toolbar>
  
      <v-data-table
        :headers="headers"
        :items="projects"
        style="width: 100%"
        class="elevation-1"
      >

   
      
      <template v-slot:item="{ item, index }">
          <tr :class="{ 'odd-row': index % 2 === 1, 'even-row': index % 2 === 0 }">
            <td >
              <v-btn @click="openDialog(item.id)" color="primary">P1</v-btn>
            </td>
            <td>
              <v-btn @click="openDialog2(item.id)" color="primary">P2</v-btn>
            </td>
            <td>
              <v-btn @click="openDialog3(item.id)" color="primary">P3</v-btn>
            </td>
            <td>{{ item.id }}</td>
            <td>{{ item.no }}</td>
            <td>{{ item.projectName }}</td>
            <td>{{ item.projectType }}</td>
            <td>{{ item.location }}</td>
            <td>{{ item.eumPicName }}</td>
            <td>{{ item.eumPicContact }}</td>
            <td>{{ item.branch }}</td>
            <td>{{ item.agentComm }}</td>
            <td>{{ item.advanceComm }}</td>
            <td>{{ item.rebate }}</td>
            <td>{{ item.status }}</td>
            <td>{{ item.title }}</td>
            <td>{{ item.tenure }}</td>
            <td>{{ item.priceRange }}</td>
            <td>{{ item.sizeRange }}</td>
            <td>{{ item.totalUnit }}</td>
         
            <td>{{ item.totalStorey }}</td>
            
            <td>{{ item.completionDate }}</td>
            <td>{{ item.developer }}</td>
            
       
      
    
          </tr>
        </template>
  
        <template v-slot:no-data>
          <v-btn disabled>No Projects Found</v-btn>
        </template>
      </v-data-table>
  
      <v-progress-linear v-if="loading" indeterminate color="primary"></v-progress-linear>
  
      <v-alert v-if="error" type="error">
        Error loading projects: {{ error }}
      </v-alert>
  
      <!-- Dialog for PasteProjectDetail -->
      <v-dialog v-model="dialog" max-width="800px">
        <v-card>
          <v-card-title>
            <span class="headline">Paste 1</span>
          </v-card-title>
          <v-card-text>
            <PasteProjectHdPart1 :projectId="selectedProjectId" />
          </v-card-text>
          <v-card-actions>
            <v-btn color="primary" @click="closeDialog">Close</v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>

      <v-dialog v-model="dialog2" max-width="800px">
        <v-card>
          <v-card-title>
            <span class="headline2">Paste 2</span>
          </v-card-title>
          <v-card-text>
              <PasteProjectHdPart2 :projectId="selectedProjectId" />
          </v-card-text>
          <v-card-actions>
            <v-btn color="primary" @click="closeDialog2">Close</v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>

      <v-dialog v-model="dialog3" max-width="800px">
        <v-card>
          <v-card-title>
            <span class="headline2">Paste 3</span>
          </v-card-title>
          <v-card-text>
            <PasteProjectHdPart3 :projectId="selectedProjectId" />
          </v-card-text>
          <v-card-actions>
            <v-btn color="primary" @click="closeDialog3">Close</v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>
    </v-container>
  </template>
  
  <script>
  import 'vuetify/styles'; // Ensure Vuetify styles are included
  import { ref, onMounted } from 'vue';
  import { loadAllProjects } from '../utils/contactUtils';
  import PasteProjectHdPart3 from './pasteProjectHdPart3.vue';
  import PasteProjectHdPart1 from './PasteProjectHdPart1.vue';
  import PasteProjectHdPart2 from './PasteProjectHdPart2.vue';
  

  export default {
    name: 'ProjectListing',
    components: {
       PasteProjectHdPart3,PasteProjectHdPart1,PasteProjectHdPart2
    },
    setup() {
      const headers = [
        { text: 'P1', title: 'P1' },
        { text: 'P2', title: 'P2' },
        { text: 'P3', title: 'P3' },
        { text: 'ID', title: 'ID', value: 'id' },
        { text: 'No', title: 'No', value: 'no' },
        { text: 'Project Name', title: 'Project Name', value: 'projectName' },
        { text: 'Project Type', title: 'Project Type', value: 'projectType' },
        { text: 'Location', title: 'Location', value: 'location' },
        { text: 'EUM PIC NAME', title: 'EUM PIC NAME', value: 'eumPicName' },
        { text: 'EUM PIC Contact', title: 'EUM PIC Contact', value: 'eumPicContact' },
        { text: 'Branch', title: 'Branch', value: 'branch' },
        { text: 'Agent Comm', title: 'Agent Comm', value: 'agentComm' },
        { text: 'Advance Comm', title: 'Advance Comm', value: 'advanceComm' },
       
        { text: 'Rebate', title: 'Rebate', value: 'rebate' },
        { text: 'Status', title: 'Status', value: 'status' },
        { text: 'Title', title: 'Title', value: 'title' },
        { text: 'Tenure', title: 'Tenure', value: 'tenure' },
        { text: 'Price Range', title: 'Price Range', value: 'priceRange' },
        { text: 'Size Range', title: 'Size Range', value: 'sizeRange' },
 

        { text: 'Total Unit', title: 'Total Unit', value: 'totalUnit' },
        { text: 'Total Storey', title: 'Total Storey', value: 'totalStorey' },

        { text: 'Developer', title: 'Developer', value: 'developer' },
        { text: 'Actions', value: 'actions' }, // Column for the button
        { text: 'Completion Date', title: 'Completion Date', value: 'completionDate' },
      ];
  
      const projects = ref([]);
      const loading = ref(false);
      const error = ref(null);
      const dialog = ref(false); // Control the dialog visibility
      const dialog2 = ref(false); // Control the dialog visibility
      const dialog3 = ref(false); 
      const selectedProjectId = ref(null); // Store the selected project ID
  
      onMounted(async () => {
        loading.value = true;
        try {
          projects.value = await loadAllProjects();
        } catch (err) {
          error.value = err.message || 'Failed to load projects';
          console.error('Error loading projects:', err);
        } finally {
          loading.value = false;
        }
      });
  
      const openDialog = (id) => {
         selectedProjectId.value = id; // Set the selected project ID
        dialog.value = true; // Open the dialog
      };
  

      const openDialog2 = (id) => {
         selectedProjectId.value = id; // Set the selected project ID
        dialog2.value = true; // Open the dialog
      };
  
      const openDialog3 = (id) => {
        console.log('Opening dialog 3 with id:', id); // Debugging
         selectedProjectId.value = id; // Set the selected project ID
        dialog3.value = true; // Open the dialog
      };

      const closeDialog = () => {
        dialog.value = false; // Close the dialog
   //     selectedProjectId.value = null; // Reset the selected project ID
      };
  
      const closeDialog2 = () => {
        dialog2.value = false; // Close the dialog
   //     selectedProjectId.value = null; // Reset the selected project ID
      };
  
      const closeDialog3 = () => {
        dialog3.value = false; // Close the dialog
   //     selectedProjectId.value = null; // Reset the selected project ID
      };
      return {
        headers,
        projects,
        loading,
        error,
        openDialog,
        openDialog2,
        openDialog3,
        closeDialog,
        closeDialog2,
        closeDialog3,
        dialog,
        dialog2,
        dialog3,
        selectedProjectId,
      };
    },
  };
  </script>
  
  <style scoped>
  .elevation-1 {
    min-height: 300px;
  }

  .elevation-1 {
    min-height: 300px;
  }
  
  .odd-row {
    background-color: #e5f5f5; /* Light grey background for odd rows */
  }
  
  .even-row {
    background-color: #ffffff; /* White background for even rows */
  }

 
  </style>
 


