<template>
    <div>
        <h1>Project Data for {{ projectName }}</h1>
        <table>
            <thead>
                <tr>
                    <!-- Clicking this row will toggle the additional fields -->
                    <th @click="toggleExpanded">Project Name</th>

                    <th @click="toggleExpanded">Category</th>
                    <th @click="toggleExpanded">Developer</th>
                    <th @click="toggleExpanded">Completion Date</th>

                    <th title="Master, strata or individual titles."  @click="toggleExpanded">Title Type</th>
         
                    <th title="Freehold, Leasehold" @click="toggleExpanded">Tenure</th>
                    <th @click="toggleExpanded">Year Built</th>
                    <th @click="toggleExpanded" class="table-column-width-3">Address</th>
                    <th @click="toggleExpanded">Land Dimension</th>


                    <th @click="toggleExpanded">Actions</th>
                </tr>
                <!-- Conditionally render additional header fields when expanded is true -->

            </thead>
            <tbody>
                <tr v-if="projects.length === 0">
                    <td colspan="6" class="text-center">No data available</td>
                </tr>
                <tr v-for="project in projects" :key="project.id">
                    <td>{{ project.name }}</td>

                    <td width="5%">{{ project.category }}</td>
                    <td>{{ project.developer }}</td>
                    <td>{{ project.completionDate || 'N/A' }}</td>
                    <td>{{ project.titleType }}</td>
          
                    <td>{{ project.tenure }}</td>
                    <td>{{ project.yearBuild }}</td>
                    <td width="30%">{{ project.address }}</td>
                    <td>{{ project.landDimension }}</td>


                    <td>
                        <button @click="editProject(project)">Edit</button>
                        <button @click="deleteProject(project)">Delete</button>
                    </td>
                </tr>

                <!-- Expandable unit details -->

            </tbody>
        </table>
        <table>
            <thead>
                <tr>
                    <!--                                                
                   
                    propertyType
                    projectUrl
                    DocUrl
                    lotStatus -->
                    <!-- Clicking this row will toggle the additional fields -->

                    <th title="Service Residence,Apartment,Condominium,Shop / Office,shop,Bungalow House,2-storey Terraced House,3-storey Terraced House" @click="toggleExpanded">propertyType</th>
                    <th @click="toggleExpanded">projectUrl</th>
                    <th @click="toggleExpanded">DocUrl</th>
                    <th @click="toggleExpanded">Lot Status</th>

                </tr>
                <!-- Conditionally render additional header fields when expanded is true -->

            </thead>
            <tbody>
                <tr v-if="projects.length === 0">
                    <td colspan="6" class="text-center">No data available</td>
                </tr>
                <tr v-for="project in projects" :key="project.id">

                    <td>{{ project.propertyType }}</td>
                    <td>{{ project.projectUrl }}</td>
                    <td>{{ project.DocUrl || 'N/A' }}</td>
                    <td>{{ project.lotStatus || 'N/A' }}</td>

                </tr>

                <!-- Expandable unit details -->

            </tbody>
        </table>
        <table v-if="expanded">
            <thead>
                <tr>
                    <!-- Clicking this row will toggle the additional fields -->

                    <th @click="toggleExpanded">Description</th>

                </tr>
                <!-- Conditionally render additional header fields when expanded is true -->

            </thead>
            <tbody>
                <tr v-if="projects.length === 0">
                    <td colspan="6" class="text-center">No data available</td>
                </tr>
                <tr v-for="project in projects" :key="project.id">

                    <td v-html="project.description"></td>

                    <td>
                        <button @click="editProject(project)">Edit</button>
                        <button @click="deleteProject(project)">Delete</button>
                    </td>
                </tr>

                <!-- Expandable unit details -->

            </tbody>
        </table>
        <template v-for="project in projects" :key="project.id">
            <tr v-if="project.layouts.length > 0">
                <td colspan="6">
                    <table>
                        <thead>
                            <tr>


                                <th>Unit Type</th>
                                <th>Description</th>
                                <th>Price</th>
                                <th>Rooms</th>
                                <th>Bathrooms</th>
                                <th>Car Parks</th>
                                <th>Build Up Area</th>
                                <th>Land Size</th>
                                <th>Units Left</th>
                                <th>Furnishing</th>
                           
                                <th>Floor1</th>
                                <th>Price1</th>


                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="unit in project.layouts" :key="unit.name">
                                <td>{{ unit.name }}</td>
                                <td v-html="unit.description"></td>
                                <td>{{ unit.price }}</td>
                                <td>{{ unit.room }}</td>
                                <td>{{ unit.bathRoom }}</td>
                                <td>{{ unit.carPark }}</td>
                                <td>{{ unit.buildUpArea }} sq ft</td>
                                <th>{{ unit.landSize }}</th>
                                <th>{{ unit.unitsLeft }}</th>
                                <th>{{ unit.furnishing }}</th>
                  
                                <th>{{ unit.floor1 }}</th>
                                <th>{{ unit.price1 }}</th>



                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
        </template>
    </div>
</template>

<script>
import { loadProjects } from '../utils/contactUtils.js';

export default {
    props: {
        projectName: {
            type: String,
            required: true,
        },
    },
    data() {
        return {
            projects: [],
            expanded: false, // State to toggle extra fields
        };
    },
    async mounted() {
        await this.loadProjectsData(this.projectName);
    },
    methods: {
        async loadProjectsData(projectFilter) {
            try {
                const projects = await loadProjects(projectFilter);
                console.log('Loaded projects:', projects);
                this.projects = projects;
            } catch (error) {
                console.error('Error loading projects:', error);
            }
        },
        toggleExpanded() {
            this.expanded = !this.expanded;
        },
        editProject(row) {
            console.log('Editing project:', row);
            // Implement your edit logic here
        },
        deleteProject(row) {
            console.log('Deleting project:', row);
            // Implement your delete logic here
        },
    },
};
</script>

<style scoped>
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
}

th,
td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
    cursor: pointer;
}

th {
    background-color: #f2f2f2;
}

.text-center {
    text-align: center;
}

.table-column-width-1 {
    width: 10px;
    /* Set the desired fixed width */
}

.table-column-width-2 {
    width: 20px;
    /* Set the desired fixed width */
}

.table-column-width-3 {
    width: 40px;
    /* Set the desired fixed width */
}

.table-column-width-4 {
    width: 80px;
    /* Set the desired fixed width */
}

.table-column-width-5 {
    width: 160px;
    /* Set the desired fixed width */
}
</style>
